#!/bin/zsh
# 依序生成角色設定圖（一次一張，不並行）
OUT=/Users/batman_work/claude/棒球遊戲/art/concept_v2
STYLE="Original character design, stylized 3D cartoon render like a modern animated feature film, soft subsurface skin, clean sculpted forms, about 4 heads tall (not chibi, not realistic), slightly large head, sturdy athletic body with readable shoulders, waist and knees. Uniform: cream-white baseball jersey with dark green piping and buttons, cream-white pants with belt, dark green stirrup socks, black cleats with laces. Neutral light grey background, even studio lighting, no text, no logos, no watermark."
[ -f $OUT/body_turnaround.png ] || codex exec --skip-git-repo-check "請用內建 image_gen 工具產一張橫式 1536x1024 PNG。內容：character turnaround sheet of ONE baseball player standing in a relaxed A-pose, arms slightly away from body, three views side by side at the same scale and same height: front view, left side view, back view. Wearing a dark green baseball cap. Short black hair visible under the cap, confident determined eyes, small sculpted nose and mouth. ${STYLE} 完成後把產出複製到絕對路徑 ${OUT}/body_turnaround.png 並用 sips 縮放到寬 1536。回報 OK 即可。"
[ -f $OUT/head_variants.png ] || codex exec --skip-git-repo-check "請用內建 image_gen 工具產一張橫式 1536x1024 PNG。內容：head and shoulders lineup sheet of 8 DIFFERENT original baseball players, 4 columns x 2 rows, all facing the front, NO caps so the hairstyles are visible. Each has a clearly different face shape, hairstyle, skin tone and facial hair: 1) short black undercut with light stubble, 2) wavy brown medium hair, 3) curly black hair with full beard, dark skin, 4) blond short spiky hair, fair skin, 5) black buzz cut, round face, 6) long brown hair tied back with mustache, 7) neat side-part black hair, young clean face, 8) messy dark brown hair with goatee, tan skin. All with determined confident expressions, cream-white jersey collars with dark green piping. ${STYLE} 完成後把產出複製到絕對路徑 ${OUT}/head_variants.png 並用 sips 縮放到寬 1536。回報 OK 即可。"
echo 完成; ls -la $OUT
